package ocr

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"unicode"
)

// PDF invoices (ADR 0018). Most supplier invoices arrive as PDFs generated by
// software, so they carry a text layer. Reading that text is exact, and OCR on
// it would only add errors. Scanned PDFs have no text layer, so their first
// page is rendered to an image and goes through tesseract like a photo.
//
// Both steps use poppler's command-line tools as subprocesses, for the same
// reasons tesseract does (ADR 0011): no cgo, argv only, a temp file, a
// timeout. Both are optional. Without them a PDF is still stored as the Beleg,
// only nothing is pre-filled.

var (
	pdfOnce             sync.Once
	pdftotext, pdftoppm string
)

func pdfTools() (string, string) {
	pdfOnce.Do(func() {
		if p, err := exec.LookPath("pdftotext"); err == nil {
			pdftotext = p
		}
		if p, err := exec.LookPath("pdftoppm"); err == nil {
			pdftoppm = p
		}
	})
	return pdftotext, pdftoppm
}

// IsPDF reports whether data is a PDF, by its magic bytes rather than a name.
func IsPDF(data []byte) bool { return bytes.HasPrefix(data, []byte("%PDF-")) }

// PDFAvailable reports whether a PDF can be read at all: through its text
// layer, or by rendering and OCR.
func PDFAvailable() bool {
	text, raster := pdfTools()
	return text != "" || (raster != "" && Available())
}

// Available reports whether anything can be read from an upload: a photo
// needs tesseract, a PDF needs poppler (and tesseract if it is scanned).
func AnyAvailable() bool { return Available() || PDFAvailable() }

// minTextLayer is how many letters and digits a text layer needs before it
// counts as real. A scanned PDF often carries a few stray characters (a page
// number, a scanner stamp) that are not the invoice.
const minTextLayer = 40

// ErrNoReader is returned when nothing is installed that could read the file.
var ErrNoReader = fmt.Errorf("no text recognition is installed for this file type")

// Read returns the text of an uploaded Beleg, a photo or a PDF, and says how
// it was obtained ("text layer", "OCR"). The caller extracts a draft from it.
func Read(ctx context.Context, data []byte, filename string) (text, method string, err error) {
	if !IsPDF(data) {
		if !Available() {
			return "", "", ErrNoReader
		}
		text, err := Recognise(ctx, data, filename)
		return text, "OCR", err
	}
	if len(data) > MaxImageSize {
		return "", "", fmt.Errorf("the PDF is larger than %d MiB", MaxImageSize>>20)
	}

	textBin, rasterBin := pdfTools()
	if textBin == "" && (rasterBin == "" || !Available()) {
		return "", "", ErrNoReader
	}

	dir, err := os.MkdirTemp("", "bookkeeper-pdf-")
	if err != nil {
		return "", "", err
	}
	defer os.RemoveAll(dir)
	in := filepath.Join(dir, "beleg.pdf")
	if err := os.WriteFile(in, data, 0o600); err != nil {
		return "", "", err
	}

	ctx, cancel := context.WithTimeout(ctx, Timeout)
	defer cancel()

	var layerErr error
	if textBin != "" {
		// -layout keeps a label and its amount on one line ("Gesamtbetrag
		// 1.234,56"), which is what the extraction rules look for. Only the
		// first three pages: the total and the date are at the front, and
		// terms and conditions at the back only add noise.
		text, layerErr = runTool(ctx, textBin, "-layout", "-enc", "UTF-8", "-f", "1", "-l", "3", in, "-")
		if layerErr == nil && meaningful(text) >= minTextLayer {
			return text, "text layer", nil
		}
	}

	// No usable text layer: a scan. Render page 1 and read it like a photo.
	if rasterBin == "" || !Available() {
		if layerErr != nil {
			return "", "", layerErr
		}
		return "", "", fmt.Errorf("the PDF has no text layer (a scan?), and OCR is not installed")
	}
	out := filepath.Join(dir, "page")
	if _, err := runTool(ctx, rasterBin, "-r", "300", "-png", "-f", "1", "-l", "1", "-singlefile", in, out); err != nil {
		return "", "", err
	}
	png, err := os.ReadFile(out + ".png")
	if err != nil {
		return "", "", fmt.Errorf("render PDF page: %w", err)
	}
	text, err = Recognise(ctx, png, "page.png")
	return text, "OCR of page 1", err
}

func runTool(ctx context.Context, bin string, args ...string) (string, error) {
	var stdout, stderr bytes.Buffer
	cmd := exec.CommandContext(ctx, bin, args...)
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg == "" {
			msg = err.Error()
		}
		return "", fmt.Errorf("%s: %s", filepath.Base(bin), msg)
	}
	return stdout.String(), nil
}

func meaningful(s string) int {
	n := 0
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			n++
		}
	}
	return n
}
